<template>
  <div class="product-page api-page">
    <header class="page-heading"><div><h1>API 接口文档</h1><p>从仓库版本化 OpenAPI 契约实时生成，覆盖业务核心、AI 辅助服务与医院适配器边界。</p></div><div class="page-heading-actions"><el-button :icon="Braces">下载契约</el-button><el-button type="primary" :icon="Play" :disabled="true">在线调试未连接</el-button></div></header>
    <div class="contract-banner"><FileCheck2 :size="18"/><div><strong>OpenAPI 3.0.3 · 契约唯一来源</strong><span>页面只展示契约中已声明的接口；请求执行在连接开发环境后启用，不会向真实医院系统发送测试数据。</span></div><el-tag type="success" effect="plain">{{ operations.length }} OPERATIONS</el-tag></div>
    <section class="summary-strip"><div v-for="spec in specs" :key="spec.key"><span>{{ spec.title }}</span><strong>{{ spec.operations.length }}</strong><small>v{{ spec.version }} · {{ spec.file }}</small></div><div><span>契约状态</span><strong>3 / 3</strong><small>解析成功 · 无页面私有接口</small></div></section>
    <div class="toolbar-row"><el-input v-model="query" :prefix-icon="Search" placeholder="搜索路径、说明或关联页面" clearable/><el-select v-model="service"><el-option label="全部服务" value="全部"/><el-option v-for="spec in specs" :key="spec.key" :label="spec.title" :value="spec.key"/></el-select><el-select v-model="method"><el-option label="全部方法" value="全部"/><el-option v-for="item in methods" :key="item" :label="item" :value="item"/></el-select><el-button :icon="RotateCcw" @click="reset">重置</el-button></div>
    <div class="api-layout">
      <section class="surface-panel endpoint-list"><div class="surface-panel-header"><h2>接口目录</h2><span>{{ filtered.length }} 个操作</span></div><button v-for="operation in filtered" :key="operation.key" :class="{active:active?.key===operation.key}" @click="active=operation"><span class="method-badge" :class="operation.method.toLowerCase()">{{ operation.method }}</span><span><strong>{{ operation.path }}</strong><small>{{ operation.summary }}</small></span><ChevronRight :size="15"/></button></section>
      <section v-if="active" class="surface-panel endpoint-detail"><header><div><span class="method-badge" :class="active.method.toLowerCase()">{{ active.method }}</span><code>{{ active.path }}</code></div><span class="service-chip">{{ active.serviceTitle }} · v{{ active.version }}</span></header><div class="endpoint-body"><h2>{{ active.summary }}</h2><div class="page-link"><LayoutPanelTop :size="16"/><div><span>对应功能页面</span><strong>{{ active.page }}</strong></div></div><dl class="contract-meta"><div><dt>服务边界</dt><dd>{{ active.boundary }}</dd></div><div><dt>契约文件</dt><dd><code>{{ active.file }}</code></dd></div><div><dt>鉴权要求</dt><dd>{{ active.auth }}</dd></div><div><dt>数据级别</dt><dd>{{ active.dataClass }}</dd></div></dl><h3>参数与请求</h3><div v-if="active.parameters.length" class="parameter-table"><div class="parameter-row heading"><span>名称</span><span>位置</span><span>必填</span><span>类型</span></div><div v-for="parameter in active.parameters" :key="parameter.name" class="parameter-row"><code>{{ parameter.name }}</code><span>{{ parameter.in }}</span><span>{{ parameter.required?'是':'否' }}</span><span>{{ parameter.type }}</span></div></div><div v-else class="empty-contract">契约未声明路径或查询参数；请求体结构以 OpenAPI components 为准。</div><h3>响应</h3><div class="response-list"><div v-for="response in active.responses" :key="response.code"><span class="response-code">{{ response.code }}</span><span>{{ response.description }}</span></div></div><h3>调用约束</h3><ul class="boundary-list"><li v-for="item in active.constraints" :key="item"><ShieldCheck :size="14"/>{{ item }}</li></ul></div></section>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { parse } from 'yaml'
import { Braces, ChevronRight, FileCheck2, LayoutPanelTop, Play, RotateCcw, Search, ShieldCheck } from 'lucide-vue-next'
import coreRaw from '../../../../contracts/openapi/core-api.v1.yaml?raw'
import aiRaw from '../../../../contracts/openapi/ai-service.v1.yaml?raw'
import hisRaw from '../../../../contracts/openapi/his-adapter.v1.yaml?raw'

type Parameter={name:string;in:string;required:boolean;type:string}
type Operation={key:string;service:string;serviceTitle:string;version:string;file:string;method:string;path:string;summary:string;parameters:Parameter[];responses:{code:string;description:string}[];page:string;boundary:string;auth:string;dataClass:string;constraints:string[]}
type OpenApiDocument={info:{title:string;version:string};paths:Record<string,Record<string,{summary?:string;parameters?:Array<{name:string;in:string;required?:boolean;schema?:{type?:string}}> ;responses?:Record<string,{description?:string}>}>>}
const sources=[{key:'core',file:'core-api.v1.yaml',raw:coreRaw},{key:'ai',file:'ai-service.v1.yaml',raw:aiRaw},{key:'his',file:'his-adapter.v1.yaml',raw:hisRaw}]
const pageFor=(path:string)=>path.includes('/workbench')||path==='/api/worklist'?'医生工作区':path.includes('/pharmacist')||path.includes('/adr/')||path.includes('/collaboration/')?'药师工作区':path.includes('/rules')||path.includes('/dose/')?'临床规则管理':path.includes('/evidence/')?'证据资料中心':path.includes('/research/')?'科研工作台':path.includes('/knowledge/')?'知识审核中心':path.includes('/integration/')||path.startsWith('/v1/his/')||path.includes('/prescription-draft')?'接口与同步':path.includes('/recommendation')?'处方辅助决策':'系统管理'
const boundaryFor=(service:string)=>service==='core'?'正式状态、权限、审计与确定性规则的唯一权威服务':service==='ai'?'只执行受控检索、解释草稿与固定版本统计，不改变正式状态':'隔离医院字段、身份和传输差异，只允许处方草稿回写'
const specs=sources.map(source=>{const document=parse(source.raw) as OpenApiDocument;const operations:Operation[]=[];for(const [path,item] of Object.entries(document.paths)){for(const [method,operation] of Object.entries(item)){if(!['get','post','put','patch','delete'].includes(method))continue;operations.push({key:`${source.key}:${method}:${path}`,service:source.key,serviceTitle:document.info.title,version:document.info.version,file:source.file,method:method.toUpperCase(),path,summary:operation.summary||'契约未提供摘要',parameters:(operation.parameters||[]).map(parameter=>({name:parameter.name,in:parameter.in,required:Boolean(parameter.required),type:parameter.schema?.type||'object'})),responses:Object.entries(operation.responses||{}).map(([code,response])=>({code,description:response.description||'契约响应'})),page:pageFor(path),boundary:boundaryFor(source.key),auth:source.key==='his'?'服务身份 + mTLS（医院接入配置）':'OIDC/医院 SSO 映射角色 + 最小权限',dataClass:source.key==='ai'?'去标识化受控上下文':source.key==='his'?'医院适配边界数据':'统一医疗模型与审计数据',constraints:source.key==='core'?['硬阻断不可由任何角色绕过','所有状态变更写入不可删除审计事件','正式医嘱不在本系统创建']:source.key==='ai'?['不得确认过敏、发布规则或生成确定性剂量','无证据时必须返回证据不足','失败时核心安全审查保持可用']:['使用幂等键处理重复事件与草稿写入','旧版本更新不得覆盖较新事实','回写对象始终是处方草稿而非正式医嘱']})}}return{...source,title:document.info.title,version:document.info.version,operations}})
const operations=specs.flatMap(spec=>spec.operations);const query=ref('');const service=ref('全部');const method=ref('全部');const methods=[...new Set(operations.map(item=>item.method))];const active=ref<Operation|undefined>(operations[0])
const filtered=computed(()=>operations.filter(item=>(service.value==='全部'||item.service===service.value)&&(method.value==='全部'||item.method===method.value)&&(!query.value||`${item.path} ${item.summary} ${item.page}`.toLowerCase().includes(query.value.toLowerCase()))))
watch(filtered,value=>{if(!value.some(item=>item.key===active.value?.key))active.value=value[0]})
function reset(){query.value='';service.value='全部';method.value='全部'}
</script>

<style scoped>
.contract-banner{display:flex;align-items:center;gap:9px;margin-bottom:10px;padding:10px 12px;border:1px solid #bdd8d1;border-radius:5px;background:#eef8f5;color:#245e51}.contract-banner>div{display:grid;flex:1;gap:2px}.contract-banner strong{font-size:10px}.contract-banner span{font-size:8px}.api-layout{display:grid;grid-template-columns:minmax(420px,38%) minmax(0,62%);gap:10px;min-height:540px}.endpoint-list{overflow:hidden}.endpoint-list>button{width:100%;display:grid;grid-template-columns:48px minmax(0,1fr) 18px;align-items:center;gap:8px;padding:9px 11px;border:0;border-bottom:1px solid #e3e9eb;background:#fff;text-align:left;cursor:pointer}.endpoint-list>button:hover,.endpoint-list>button.active{background:#edf6f4}.endpoint-list>button.active{box-shadow:inset 3px 0 #17766e}.endpoint-list button>span:nth-child(2){min-width:0;display:grid;gap:3px}.endpoint-list strong{overflow:hidden;text-overflow:ellipsis;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:8px;white-space:nowrap}.endpoint-list small{overflow:hidden;color:#738188;font-size:7px;text-overflow:ellipsis;white-space:nowrap}.method-badge{display:inline-grid;place-items:center;min-width:42px;padding:3px 5px;border-radius:3px;background:#e8f4f1;color:#176e63;font-size:7px;font-weight:800}.method-badge.post{background:#eaf1f8;color:#326994}.method-badge.put,.method-badge.patch{background:#fff3df;color:#985b10}.method-badge.delete{background:#fae9e8;color:#a33e37}.endpoint-detail header{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 13px;border-bottom:1px solid #dce4e7;background:#f6f8f9}.endpoint-detail header>div{display:flex;align-items:center;gap:8px;min-width:0}.endpoint-detail header code{overflow-wrap:anywhere;font-size:10px;font-weight:700}.service-chip{color:#64757d;font-size:8px}.endpoint-body{padding:16px}.endpoint-body h2{margin:0 0 12px;font-size:14px}.endpoint-body h3{margin:18px 0 8px;font-size:10px}.page-link{display:flex;align-items:center;gap:8px;padding:9px 10px;border-left:3px solid #267b72;background:#edf6f4}.page-link>div{display:grid;gap:2px}.page-link span{color:#6b7b82;font-size:8px}.page-link strong{font-size:9px}.contract-meta{display:grid;grid-template-columns:1fr 1fr;margin:12px 0 0;border:1px solid #dce4e7}.contract-meta div{display:grid;gap:3px;padding:9px;border-right:1px solid #dce4e7;border-bottom:1px solid #dce4e7}.contract-meta div:nth-child(2n){border-right:0}.contract-meta div:nth-last-child(-n+2){border-bottom:0}.contract-meta dt{color:#718088;font-size:8px}.contract-meta dd{margin:0;font-size:8px}.parameter-table{border:1px solid #dce4e7}.parameter-row{display:grid;grid-template-columns:1.4fr .7fr .5fr .7fr;padding:7px 9px;border-bottom:1px solid #e4eaec;font-size:8px}.parameter-row:last-child{border-bottom:0}.parameter-row.heading{background:#f5f7f8;color:#687880;font-weight:700}.empty-contract{padding:10px;border:1px dashed #cbd7db;color:#6f7f86;font-size:8px}.response-list{display:grid;gap:5px}.response-list>div{display:grid;grid-template-columns:50px 1fr;align-items:center;gap:8px;padding:7px 9px;background:#f6f8f9;font-size:8px}.response-code{font-family:monospace;font-weight:800;color:#24705d}.boundary-list{display:grid;gap:6px;margin:0;padding:0;list-style:none}.boundary-list li{display:flex;align-items:center;gap:6px;color:#49656a;font-size:8px}@media(max-width:1450px){.api-layout{grid-template-columns:minmax(380px,42%) minmax(0,58%)}}
</style>
